/* ============================================================
   CUMBRE — Traduire (FR → ES) : lot 4, le plus gros du deck
   2026-10-06. Le module Traduire vivait sur 164 phrases pour 1 850 mots
   de vocabulaire : le déséquilibre était criant. Trois leçons, en plus,
   ne produisaient AUCUNE phrase dans le Mix — estiloindirecto, pasivase
   et conectores avaient un tableau de catégories vide dans LESSON_TRANS.
   Ce lot ouvre les trois catégories qui leur manquaient (Style indirect,
   Pasiva & se, Connecteurs), étoffe « Matices C1 » (dix phrases nues,
   sans note ni niveau, dans advanced-es4.js) et renforce toutes les
   autres catégories.
   Ajouté EN FIN de tableau → les index SRS déjà acquis ne bougent pas.
   ============================================================ */
window.TRANSLATIONS = window.TRANSLATIONS.concat([

  /* --- Matices C1 : les verbes pronominaux qui changent de sens --- */
  { fr:"Le petit est tombé et s'est mis à pleurer.", en:"El niño se cayó y se echó a llorar.", alt:["El crío se cayó y rompió a llorar."], cat:"Matices C1", point:"caerse ≠ caer bien", note:"« caerse » = chuter · « caer bien a alguien » = être sympathique à quelqu'un. Et « echarse a llorar » = fondre en larmes.", level:"B2" },
  { fr:"J'étais si fatigué que je me suis endormi dans le métro.", en:"Estaba tan cansado que me dormí en el metro.", alt:["Iba tan cansado que me quedé dormido en el metro."], cat:"Matices C1", point:"dormirse ≠ dormir", note:"« dormir » = dormir (la durée) · « dormirse » = s'endormir (le basculement). Aussi : quedarse dormido.", level:"B2" },
  { fr:"Tu te souviens de la fille qu'on avait rencontrée à Séville ?", en:"¿Te acuerdas de la chica que conocimos en Sevilla?", alt:["¿Recuerdas a la chica que conocimos en Sevilla?"], cat:"Matices C1", point:"acordarse DE / recordar + COD", note:"Deux constructions, jamais mélangées : « acordarse de algo » et « recordar algo ». « te recuerdas » n'existe pas.", level:"B2" },
  { fr:"Il ne s'entend pas avec son associé, et ça se voit.", en:"No se lleva bien con su socio, y se nota.", alt:["No se lleva con su socio, y se le nota."], cat:"Matices C1", point:"llevarse bien con + se nota", note:"« llevarse bien/mal con alguien » = s'entendre. « se nota » = ça se voit, ça se sent — tournure impersonnelle très courante.", level:"B2" },
  { fr:"Il lui est venu une idée qui a sauvé le projet.", en:"Se le ocurrió una idea que salvó el proyecto.", alt:["Tuvo una idea que salvó el proyecto."], cat:"Matices C1", point:"ocurrírsele algo a alguien", note:"L'idée est sujet, la personne au datif : « se le ocurrió una idea ». Littéralement : une idée lui est survenue.", level:"C1" },
  { fr:"Elle a refusé de signer sans avoir lu le contrat.", en:"Se negó a firmar sin haber leído el contrato.", alt:["Se negó a firmar sin leer el contrato."], cat:"Matices C1", point:"negarse A ≠ negar", note:"« negar » = nier · « negarse a + infinitif » = refuser de. Et « sin haber leído » = sans avoir lu (infinitif composé).", level:"C1" },
  { fr:"On s'est donné rendez-vous samedi devant le cinéma.", en:"Hemos quedado el sábado delante del cine.", alt:["Quedamos el sábado delante del cine."], cat:"Matices C1", point:"quedar (en) ≠ quedarse", note:"« quedar con alguien » = se donner rendez-vous · « quedarse » = rester sur place. Deux verbes différents.", level:"B2" },
  { fr:"Emporte le parapluie, il va pleuvoir.", en:"Llévate el paraguas, que va a llover.", alt:["Llévate el paraguas, porque va a llover."], cat:"Matices C1", point:"llevarse (emporter) + que causal", note:"« llevarse algo » = emporter. Et ce « que » familier en tête de proposition = car, parce que.", level:"B2" },

  /* --- Matices C1 : la probabilité et la conjecture --- */
  { fr:"Il ne répond pas : il doit être en réunion.", en:"No contesta: estará reunido.", alt:["No contesta: debe de estar reunido."], cat:"Matices C1", point:"futur de conjecture", note:"Supposition au présent → futur : « estará ». L'équivalent exact de notre « il doit être ».", level:"C1" },
  { fr:"Ils devaient être en train de dîner quand nous avons appelé.", en:"Estarían cenando cuando llamamos.", alt:["Debían de estar cenando cuando llamamos."], cat:"Matices C1", point:"conditionnel + gérondif (conjecture passée)", note:"« estarían cenando » = ils devaient être en train de dîner. Le conditionnel porte la supposition, le gérondif la durée.", level:"C1" },
  { fr:"Les lumières sont éteintes : il ne doit y avoir personne.", en:"Las luces están apagadas: no habrá nadie.", alt:["Las luces están apagadas: no debe de haber nadie."], cat:"Matices C1", point:"haber au futur de conjecture", note:"« no habrá nadie » = il ne doit y avoir personne. Le futur ne parle pas d'avenir ici, mais d'hypothèse.", level:"C1" },
  { fr:"Il a réussi sans rien réviser : il doit être très doué.", en:"Ha aprobado sin estudiar nada: tiene que ser muy listo.", alt:["Ha aprobado sin estudiar nada: debe de ser muy listo."], cat:"Matices C1", point:"tener que (déduction quasi certaine)", note:"« tener que + inf. » marque la déduction forte ; « deber de + inf. » une probabilité plus prudente.", level:"C1" },
  { fr:"Prends un manteau : il se peut qu'il fasse froid ce soir.", en:"Coge un abrigo: puede que haga frío esta noche.", alt:["Llévate un abrigo: puede que haga frío esta noche."], cat:"Matices C1", point:"puede que + SUBJ", note:"« puede que » exige toujours le subjonctif : puede que haga. Jamais « puede que hace ».", level:"B2" },
  { fr:"Il viendra peut-être demain, mais je n'en suis pas sûr.", en:"A lo mejor viene mañana, pero no estoy seguro.", alt:["Igual viene mañana, pero no estoy seguro."], cat:"Matices C1", point:"a lo mejor + INDICATIF", note:"« a lo mejor » et « igual » (familier) se construisent avec l'indicatif. « quizá » et « tal vez » préfèrent le subjonctif.", level:"B2" },
  { fr:"Tu as peut-être raison : je n'y avais pas pensé comme ça.", en:"Quizás tengas razón: no lo había pensado así.", alt:["Tal vez tengas razón: no lo había pensado así."], cat:"Matices C1", point:"quizá(s) + subj. (doute)", note:"Le subjonctif marque le doute ; l'indicatif rendrait l'hypothèse presque affirmée.", level:"C1" },
  { fr:"Elle aura oublié de prévenir, comme d'habitude.", en:"Se le habrá olvidado avisar, como siempre.", alt:["Habrá olvidado avisar, como siempre."], cat:"Matices C1", point:"futur antérieur de conjecture + se me olvida", note:"« habrá olvidado » = elle aura sûrement oublié. Et « se le olvidó » = l'oubli involontaire, sans coupable.", level:"C1" },

  /* --- Matices C1 : conséquence et comparaison progressive --- */
  { fr:"Il a posé tant de questions que la réunion a duré le double.", en:"Hizo tantas preguntas que la reunión duró el doble.", alt:["Planteó tantas preguntas que la reunión duró el doble."], cat:"Matices C1", point:"tantas + nom féminin pluriel + que", note:"« tanto » s'accorde avec le nom : tantas preguntas. Et « durar el doble » = durer deux fois plus longtemps.", level:"B2" },
  { fr:"Le discours était si long que la moitié de la salle est partie.", en:"El discurso fue tan largo que media sala se marchó.", alt:["El discurso resultó tan largo que media sala se fue."], cat:"Matices C1", point:"tan + adjectif + que", note:"« tan + adjectif/adverbe + que ». Et « media sala » sans article : la moitié de la salle.", level:"B2" },
  { fr:"Il m'a plu tout de suite, dès le premier jour.", en:"Me cayó bien desde el primer día.", alt:["Me cayó simpático desde el primer día."], cat:"Matices C1", point:"caer bien a alguien", note:"Construit comme gustar : la personne jugée est sujet, celle qui juge est au datif. ⚠️ « me gusta » pour une personne a un sens amoureux.", level:"B2" },
  { fr:"Personne n'avait été prévenu, d'où la colère générale.", en:"No se avisó a nadie, de ahí que todos se enfadaran.", alt:["No avisaron a nadie, de ahí que todos se hayan enfadado."], cat:"Matices C1", point:"de ahí que + SUBJ", note:"« de ahí que » exige le subjonctif. C'est le « d'où le fait que » soutenu de l'espagnol écrit.", level:"C1" },
  { fr:"Il pleuvait, si bien que nous sommes restés à la maison.", en:"Estaba lloviendo, así que nos quedamos en casa.", alt:["Llovía, de modo que nos quedamos en casa."], cat:"Matices C1", point:"así que / de modo que + IND", note:"Conséquence réelle et constatée → indicatif. Le subjonctif après « de modo que » exprimerait un but.", level:"B1" },
  { fr:"Moins on en parle, mieux ça vaut.", en:"Cuanto menos se hable del tema, mejor.", alt:["Cuanto menos se hable de ello, mejor."], cat:"Matices C1", point:"cuanto menos + subj., mejor", note:"Tournée vers l'avenir, la corrélation passe au subjonctif : « cuanto menos se hable ». Et le second terme peut se réduire à « mejor ».", level:"C1" },
  { fr:"Plus il gagne d'argent, plus il dépense.", en:"Cuanto más dinero gana, más gasta.", alt:["Cuanto más dinero tiene, más gasta."], cat:"Matices C1", point:"cuanto más + NOM", note:"Devant un nom, « cuanto » s'accorde avec lui : cuantas más horas, cuanta más gente.", level:"C1" },
  { fr:"Il a parlé de telle manière qu'il nous a tous convaincus.", en:"Habló de tal modo que nos convenció a todos.", alt:["Habló de tal manera que nos convenció a todos."], cat:"Matices C1", point:"de tal modo/manera que", note:"Résultat constaté → indicatif. Et « convencer A alguien » garde le « a » de la personne.", level:"C1" },

  /* --- Style indirect --- */
  { fr:"Il m'a dit qu'il était fatigué et qu'il rentrait chez lui.", en:"Me dijo que estaba cansado y que se iba a casa.", alt:["Me dijo que estaba cansado y que se marchaba a casa."], cat:"Style indirect", point:"présent → imparfait", note:"Au style indirect au passé, le présent recule d'un cran : « estoy » → « estaba », « me voy » → « se iba ».", level:"B2" },
  { fr:"Elle a avoué qu'elle n'avait rien lu avant la réunion.", en:"Confesó que no había leído nada antes de la reunión.", alt:["Reconoció que no había leído nada antes de la reunión."], cat:"Style indirect", point:"perfecto/indefinido → pluscuamperfecto", note:"« no he leído » / « no leí » reculent en « no había leído ». Le plus-que-parfait est le passé du passé.", level:"B2" },
  { fr:"Il a promis qu'il nous appellerait dès son arrivée.", en:"Prometió que nos llamaría en cuanto llegara.", alt:["Prometió que nos llamaría nada más llegar."], cat:"Style indirect", point:"futur → conditionnel (+ en cuanto + subj.)", note:"« llamaré » → « llamaría ». Et « en cuanto » tourné vers l'avenir exige le subjonctif, imparfait ici par concordance.", level:"C1" },
  { fr:"Le médecin m'a dit de ne pas forcer pendant quinze jours.", en:"El médico me dijo que no forzara durante quince días.", alt:["El médico me dijo que no hiciera esfuerzos durante quince días."], cat:"Style indirect", point:"impératif → subj. imparfait", note:"Un ordre rapporté au passé passe au subjonctif imparfait : « no fuerces » → « que no forzara ».", level:"C1" },
  { fr:"Elle m'a demandé si j'avais déjà travaillé à l'étranger.", en:"Me preguntó si había trabajado alguna vez en el extranjero.", alt:["Me preguntó si alguna vez había trabajado fuera."], cat:"Style indirect", point:"question fermée rapportée : si", note:"Une question par oui/non se rapporte avec « si », sans point d'interrogation ni inversion.", level:"B2" },
  { fr:"Il m'a demandé pourquoi je ne l'avais pas prévenu.", en:"Me preguntó por qué no se lo había dicho.", alt:["Me preguntó por qué no le había avisado."], cat:"Style indirect", point:"interrogatif accentué conservé", note:"« por qué » garde son accent même au style indirect. Et attention au double pronom : « se lo había dicho ».", level:"B2" },
  { fr:"Il a dit qu'il viendrait ce jour-là, pas le lendemain.", en:"Dijo que vendría aquel día, no al día siguiente.", alt:["Dijo que iría aquel día, no al día siguiente."], cat:"Style indirect", point:"déictiques : hoy → aquel día", note:"Les repères reculent avec les temps : hoy → aquel día, mañana → al día siguiente, aquí → allí, este → aquel.", level:"C1" },
  { fr:"Ils ont annoncé que les travaux commenceraient la semaine suivante.", en:"Anunciaron que las obras empezarían la semana siguiente.", alt:["Anunciaron que las obras comenzarían la semana siguiente."], cat:"Style indirect", point:"la semana que viene → la semana siguiente", note:"« la semana que viene » (depuis le présent) devient « la semana siguiente » (depuis le passé).", level:"B2" },
  { fr:"Elle insiste pour dire qu'elle ne savait rien de l'affaire.", en:"Insiste en que no sabía nada del asunto.", alt:["Insiste en que desconocía el asunto."], cat:"Style indirect", point:"insistir EN que + indicatif (constat)", note:"« insistir en que » + indicatif quand on rapporte un fait ; + subjonctif quand on réclame quelque chose : insiste en que vayamos.", level:"C1" },
  { fr:"Il raconte partout qu'on lui aurait proposé le poste.", en:"Va contando por ahí que le habrían ofrecido el puesto.", alt:["Anda diciendo por ahí que le habrían ofrecido el puesto."], cat:"Style indirect", point:"conditionnel de l'information non confirmée", note:"Comme en français, le conditionnel signale une information qu'on ne prend pas à son compte. Et « ir/andar + gérondif » = ne pas arrêter de.", level:"C1" },
  { fr:"Je lui ai répondu que je n'avais pas encore pris de décision.", en:"Le contesté que todavía no había tomado ninguna decisión.", alt:["Le respondí que aún no había decidido nada."], cat:"Style indirect", point:"tomar una decisión + double négation", note:"« tomar una decisión » (jamais « hacer »). Et « no… ninguna » reste la négation double normale en espagnol.", level:"B2" },
  { fr:"Il a reconnu avoir menti, mais sans expliquer pourquoi.", en:"Reconoció haber mentido, pero sin explicar por qué.", alt:["Admitió que había mentido, pero sin explicar por qué."], cat:"Style indirect", point:"reconocer + infinitif composé", note:"Quand le sujet est le même, on peut condenser : « reconoció haber mentido » plutôt que « reconoció que había mentido ».", level:"C1" },

  /* --- Pasiva & se --- */
  { fr:"On vend des appartements dans tout le quartier.", en:"Se venden pisos en todo el barrio.", alt:["Se están vendiendo pisos en todo el barrio."], cat:"Pasiva & se", point:"pasiva refleja : accord au pluriel", note:"« se venden pisos » : le verbe s'accorde avec « pisos », qui est le vrai sujet. Jamais « se vende pisos ».", level:"B2" },
  { fr:"Ici, on vit bien et on dépense peu.", en:"Aquí se vive bien y se gasta poco.", alt:["Aquí se vive bien y se gasta poco dinero."], cat:"Pasiva & se", point:"se impersonnel (3e pers. sing.)", note:"Avec un verbe intransitif, le « se » est impersonnel et reste au singulier : se vive, se trabaja, se duerme.", level:"B1" },
  { fr:"On dit qu'ils vont fermer l'usine en décembre.", en:"Se dice que van a cerrar la fábrica en diciembre.", alt:["Se rumorea que van a cerrar la fábrica en diciembre."], cat:"Pasiva & se", point:"se dice que + indicatif", note:"« se dice que », « se cree que », « se sabe que » : le on impersonnel de l'information. Indicatif à l'affirmative.", level:"B2" },
  { fr:"La loi a été approuvée par une large majorité.", en:"La ley fue aprobada por una amplia mayoría.", alt:["La ley se aprobó por una amplia mayoría."], cat:"Pasiva & se", point:"ser + participe accordé (+ por)", note:"Le passif en « ser » reste réservé à l'écrit et à la presse. À l'oral, on préfère la pasiva refleja ou l'actif.", level:"C1" },
  { fr:"On a convoqué les candidats pour lundi prochain.", en:"Se convocó a los candidatos para el lunes que viene.", alt:["Convocaron a los candidatos para el lunes que viene."], cat:"Pasiva & se", point:"se + a + personne → verbe au singulier", note:"Piège classique : quand le complément est une personne précédée de « a », le verbe reste au SINGULIER. Pas « se convocaron a los candidatos ».", level:"C1" },
  { fr:"Les clés se sont perdues pendant le déménagement.", en:"Se perdieron las llaves durante la mudanza.", alt:["Se nos perdieron las llaves durante la mudanza."], cat:"Pasiva & se", point:"se + accord : l'événement sans coupable", note:"L'espagnol préfère présenter l'accident sans responsable. Avec « se nos perdieron », on ajoute à qui c'est arrivé.", level:"B2" },
  { fr:"Il est interdit de fumer dans toute l'enceinte.", en:"Se prohíbe fumar en todo el recinto.", alt:["Está prohibido fumar en todo el recinto."], cat:"Pasiva & se", point:"se prohíbe + infinitif", note:"Formule des panneaux : « se prohíbe », « se ruega », « se agradece ». L'accent de prohíbe tombe sur le i.", level:"B2" },
  { fr:"Le bâtiment a été inauguré il y a à peine deux ans.", en:"El edificio fue inaugurado hace apenas dos años.", alt:["El edificio se inauguró hace apenas dos años."], cat:"Pasiva & se", point:"hace + durée = il y a", note:"« hace dos años » = il y a deux ans. Et « apenas » = à peine, tout juste.", level:"B2" },
  { fr:"On nous a demandé de justifier chaque dépense.", en:"Nos pidieron que justificáramos cada gasto.", alt:["Se nos pidió que justificáramos cada gasto."], cat:"Pasiva & se", point:"pedir que + subjonctif", note:"« pedir que » exige le subjonctif ; au passé, l'imparfait du subjonctif par concordance : justificáramos.", level:"C1" },
  { fr:"Ces erreurs se corrigent facilement si on les repère à temps.", en:"Esos errores se corrigen fácilmente si se detectan a tiempo.", alt:["Esos fallos se corrigen fácilmente si se detectan a tiempo."], cat:"Pasiva & se", point:"deux pasivas reflejas dans la même phrase", note:"Les deux verbes s'accordent avec leur sujet pluriel : se corrigen, se detectan. Registre de notice et de mode d'emploi.", level:"B2" },
  { fr:"Le dossier a été classé sans suite faute de preuves.", en:"El caso fue archivado por falta de pruebas.", alt:["Se archivó el caso por falta de pruebas."], cat:"Pasiva & se", point:"archivar + por falta de", note:"Formule exacte de la presse judiciaire. « por falta de » = faute de, par manque de.", level:"C1" },
  { fr:"On exige trois ans d'expérience et un anglais courant.", en:"Se exigen tres años de experiencia y un inglés fluido.", alt:["Se requieren tres años de experiencia y un inglés fluido."], cat:"Pasiva & se", point:"accord avec un sujet composé", note:"Deux éléments coordonnés → verbe au pluriel : se exigen. Langue des offres d'emploi espagnoles.", level:"B2" },

  /* --- Connecteurs --- */
  { fr:"Pour commencer, il faut distinguer deux problèmes très différents.", en:"Para empezar, hay que distinguir dos problemas muy distintos.", alt:["En primer lugar, conviene distinguir dos problemas muy distintos."], cat:"Connecteurs", point:"para empezar / en primer lugar", note:"Ouverture d'exposé. « conviene + infinitif » = il convient de, registre plus soutenu que « hay que ».", level:"B2" },
  { fr:"Les chiffres sont bons ; cependant, la tendance inquiète.", en:"Los datos son buenos; sin embargo, la tendencia preocupa.", alt:["Los datos son buenos; no obstante, la tendencia preocupa."], cat:"Connecteurs", point:"sin embargo / no obstante", note:"« sin embargo » est neutre, « no obstante » plus formel. Tous deux s'encadrent de virgules.", level:"B1" },
  { fr:"Le projet coûte cher ; en revanche, il crée deux cents emplois.", en:"El proyecto es caro; en cambio, crea doscientos empleos.", alt:["El proyecto es caro; por el contrario, crea doscientos empleos."], cat:"Connecteurs", point:"en cambio (contraste) ≠ sin embargo", note:"« en cambio » met deux choses en regard ; « sin embargo » annule une attente. Nuance exigée au C1.", level:"B2" },
  { fr:"De plus, aucune étude d'impact n'a été réalisée.", en:"Además, no se realizó ningún estudio de impacto.", alt:["Asimismo, no se realizó ningún estudio de impacto."], cat:"Connecteurs", point:"además / asimismo", note:"« asimismo » est la version écrite et administrative de « además ». Ne pas confondre avec « así mismo ».", level:"B2" },
  { fr:"Puisque personne ne s'y oppose, nous passons au vote.", en:"Puesto que nadie se opone, pasamos a la votación.", alt:["Ya que nadie se opone, pasamos a la votación."], cat:"Connecteurs", point:"puesto que / ya que (cause connue)", note:"Ces deux-là introduisent une cause déjà admise ; « porque » répond à une vraie question.", level:"B2" },
  { fr:"Les délais n'ont pas été tenus ; par conséquent, le contrat est caduc.", en:"No se cumplieron los plazos; por consiguiente, el contrato queda sin efecto.", alt:["No se cumplieron los plazos; por lo tanto, el contrato queda anulado."], cat:"Connecteurs", point:"por consiguiente / por lo tanto", note:"« quedar sin efecto » = devenir caduc. « por consiguiente » appartient au registre juridique.", level:"C1" },
  { fr:"En raison de la grève, toutes les réunions ont été reportées.", en:"Debido a la huelga, se aplazaron todas las reuniones.", alt:["A causa de la huelga, se aplazaron todas las reuniones."], cat:"Connecteurs", point:"debido a + nom", note:"« debido a » est suivi d'un NOM, jamais d'un verbe conjugué. Pour une proposition : « debido a que ».", level:"B2" },
  { fr:"En ce qui concerne le budget, rien n'est encore décidé.", en:"En cuanto al presupuesto, aún no hay nada decidido.", alt:["Por lo que respecta al presupuesto, aún no hay nada decidido."], cat:"Connecteurs", point:"en cuanto a (changer de thème)", note:"« en cuanto a + nom » = quant à. ⚠️ « en cuanto + verbe » veut dire dès que : deux emplois à ne pas mélanger.", level:"C1" },
  { fr:"Autrement dit, la réforme ne changera rien pour eux.", en:"Es decir, la reforma no cambiará nada para ellos.", alt:["Dicho de otro modo, la reforma no cambiará nada para ellos."], cat:"Connecteurs", point:"es decir / dicho de otro modo", note:"Reformulation. Plus soutenu encore : « esto es », fréquent dans les textes universitaires.", level:"B1" },
  { fr:"D'une part le coût, d'autre part le calendrier : tout bloque.", en:"Por un lado el coste, por otro el calendario: todo se atasca.", alt:["Por una parte el coste, por otra el calendario: todo se atasca."], cat:"Connecteurs", point:"por un lado… por otro…", note:"Structure binaire standard de l'argumentation. « atascarse » = se bloquer, s'enliser.", level:"B2" },
  { fr:"En somme, personne n'avait anticipé une telle demande.", en:"En definitiva, nadie había previsto semejante demanda.", alt:["En resumen, nadie había previsto tal demanda."], cat:"Connecteurs", point:"en definitiva + semejante", note:"« en definitiva » = en somme, au bout du compte. Et « semejante + nom » = un tel, une telle (sans article).", level:"C1" },
  { fr:"Il n'a pas répondu ; du moins, pas par écrit.", en:"No contestó; al menos, no por escrito.", alt:["No respondió; al menos, no por escrito."], cat:"Connecteurs", point:"al menos (restriction)", note:"« al menos » = au moins, du moins. Et « por escrito » = par écrit, locution figée sans article.", level:"B2" },
  { fr:"Par ailleurs, le rapport n'a jamais été rendu public.", en:"Por otra parte, el informe nunca se hizo público.", alt:["Por lo demás, el informe nunca se hizo público."], cat:"Connecteurs", point:"por otra parte (ajout d'un angle)", note:"« hacerse público » = être rendu public. Verbe de changement d'état avec « hacerse ».", level:"B2" },
  { fr:"En fin de compte, tout dépendra de ce que décidera le juge.", en:"A fin de cuentas, todo dependerá de lo que decida el juez.", alt:["Al fin y al cabo, todo dependerá de lo que decida el juez."], cat:"Connecteurs", point:"lo que + subjonctif (futur indéterminé)", note:"« lo que decida » : ce que le juge décidera, encore inconnu → subjonctif. Et « depender DE ».", level:"C1" },

  /* --- Subjonctif --- */
  { fr:"Je ne crois pas que ce soit une bonne idée de l'appeler maintenant.", en:"No creo que sea buena idea llamarlo ahora.", alt:["No me parece buena idea llamarlo ahora."], cat:"Subjonctif", point:"no creer que + subj.", note:"« creo que » + indicatif, mais « no creo que » + subjonctif. La négation fait basculer le mode.", level:"B2" },
  { fr:"Dès que tu auras les résultats, préviens-moi.", en:"En cuanto tengas los resultados, avísame.", alt:["Nada más tener los resultados, avísame."], cat:"Subjonctif", point:"en cuanto + subj. (futur)", note:"Toutes les conjonctions temporelles tournées vers l'avenir exigent le subjonctif : cuando, en cuanto, hasta que, mientras.", level:"B2" },
  { fr:"Je resterai jusqu'à ce que tout soit réglé.", en:"Me quedaré hasta que todo esté resuelto.", alt:["Me quedaré hasta que se solucione todo."], cat:"Subjonctif", point:"hasta que + subj.", note:"« resuelto » est le participe irrégulier de resolver. Et « quedarse » = rester (pas « quedar »).", level:"B2" },
  { fr:"Il cherche un appartement qui ait de la lumière et un ascenseur.", en:"Busca un piso que tenga luz y ascensor.", alt:["Busca un piso con luz y ascensor."], cat:"Subjonctif", point:"relative à antécédent indéfini", note:"L'appartement n'existe pas encore pour lui → subjonctif. S'il le connaissait : « que tiene luz ».", level:"B2" },
  { fr:"Je te le dis pour que tu ne l'apprennes pas par quelqu'un d'autre.", en:"Te lo digo para que no te enteres por otra persona.", alt:["Te lo cuento para que no lo sepas por otro."], cat:"Subjonctif", point:"para que + subj. (deux sujets)", note:"« para que » + subjonctif quand les sujets diffèrent. Même sujet → « para + infinitif ».", level:"B2" },
  { fr:"Il est possible qu'ils aient déjà pris leur décision.", en:"Es posible que ya hayan tomado una decisión.", alt:["Puede que ya hayan tomado una decisión."], cat:"Subjonctif", point:"subj. passé composé", note:"Fait probablement accompli → « haya + participe ». Et « tomar una decisión », jamais « hacer ».", level:"C1" },
  { fr:"Ça m'étonne qu'il n'ait rien dit pendant la réunion.", en:"Me extraña que no dijera nada durante la reunión.", alt:["Me sorprende que no dijera nada en la reunión."], cat:"Subjonctif", point:"verbe d'émotion + subj. imparfait", note:"Réaction au présent sur un fait passé → subjonctif imparfait : « que no dijera ». « que no haya dicho » marche aussi, plus proche du présent.", level:"C1" },
  { fr:"Quoi qu'il arrive, ne signe rien avant lundi.", en:"Pase lo que pase, no firmes nada antes del lunes.", alt:["Ocurra lo que ocurra, no firmes nada antes del lunes."], cat:"Subjonctif", point:"redoublement du subjonctif (concession)", note:"Structure très espagnole : « pase lo que pase », « digan lo que digan », « sea como sea ».", level:"C1" },
  { fr:"Je ne connais personne qui parle aussi bien l'arabe.", en:"No conozco a nadie que hable tan bien el árabe.", alt:["No conozco a nadie que domine así el árabe."], cat:"Subjonctif", point:"antécédent inexistant → subj.", note:"Après « no hay nadie que », « no conozco a nadie que », le subjonctif est obligatoire.", level:"B2" },
  { fr:"Il vaudrait mieux que nous en parlions en privé.", en:"Más valdría que lo habláramos en privado.", alt:["Sería mejor que lo habláramos en privado."], cat:"Subjonctif", point:"más valdría que + subj. imparfait", note:"Conditionnel dans la principale → subjonctif imparfait dans la subordonnée. La concordance est stricte.", level:"C1" },
  { fr:"Qu'il vienne ou non, la réunion aura lieu.", en:"Venga o no, la reunión se celebrará.", alt:["Tanto si viene como si no, la reunión se celebrará."], cat:"Subjonctif", point:"subj. de concession + celebrarse", note:"« venga o no » = qu'il vienne ou non. Et une réunion « se celebra » en espagnol : elle a lieu.", level:"C1" },
  { fr:"On lui a demandé de rendre le rapport avant vendredi.", en:"Le pidieron que entregara el informe antes del viernes.", alt:["Le solicitaron que entregara el informe antes del viernes."], cat:"Subjonctif", point:"pedir que + subj. imparfait", note:"« entregar » = remettre, rendre (un travail). Et le datif « le » est obligatoire avec pedir.", level:"B2" },

  /* --- Le passé --- */
  { fr:"Hier, pendant que je préparais le dîner, la lumière a sauté.", en:"Ayer, mientras preparaba la cena, se fue la luz.", alt:["Ayer, mientras hacía la cena, se fue la luz."], cat:"Passé", point:"imparfait (décor) vs indefinido (fait)", note:"« preparaba » plante le décor, « se fue » est l'événement. Et « irse la luz » = sauter, pour le courant.", level:"B1" },
  { fr:"Cette semaine, j'ai lu deux romans et je n'ai pas allumé la télé.", en:"Esta semana he leído dos novelas y no he encendido la tele.", alt:["Esta semana me he leído dos novelas y no he puesto la tele."], cat:"Passé", point:"perfecto : période non close", note:"« esta semana », « hoy », « este año » → pretérito perfecto en Espagne. En Amérique latine, l'indefinido domine.", level:"B1" },
  { fr:"Quand je suis arrivé, ils avaient déjà commencé sans moi.", en:"Cuando llegué, ya habían empezado sin mí.", alt:["Cuando llegué, ya habían comenzado sin mí."], cat:"Passé", point:"pluscuamperfecto", note:"Le fait antérieur à un autre fait passé → « habían empezado ». Et « sin mí » (pronom tonique après préposition).", level:"B1" },
  { fr:"Il a vécu dix ans à Lima avant de revenir à Madrid.", en:"Vivió diez años en Lima antes de volver a Madrid.", alt:["Estuvo diez años en Lima antes de regresar a Madrid."], cat:"Passé", point:"indefinido pour une durée close", note:"Durée achevée et bornée → indefinido. Avec « lleva diez años en Lima », on dirait qu'il y est encore.", level:"B2" },
  { fr:"Je ne savais pas qu'ils s'étaient séparés l'année dernière.", en:"No sabía que se habían separado el año pasado.", alt:["No tenía ni idea de que se habían separado el año pasado."], cat:"Passé", point:"saber à l'imparfait = ignorance durable", note:"« no sabía » = je ne savais pas (état). « no supe » voudrait dire : je ne l'ai pas appris, je ne l'ai pas su.", level:"B2" },
  { fr:"Il connaissait la ville, mais il n'y avait jamais travaillé.", en:"Conocía la ciudad, pero nunca había trabajado allí.", alt:["Conocía la ciudad, aunque nunca había trabajado allí."], cat:"Passé", point:"conocer imparfait vs indefinido", note:"« conocía » = il connaissait ; « conoció » = il a fait la connaissance. Changement de sens, pas seulement d'aspect.", level:"B2" },
  { fr:"Nous venions de sortir quand l'orage a éclaté.", en:"Acabábamos de salir cuando estalló la tormenta.", alt:["Acababa de salir cuando estalló la tormenta."], cat:"Passé", point:"acabar de à l'imparfait", note:"« acababa de + infinitif » = venait de. Jamais à l'indefinido dans ce sens.", level:"C1" },
  { fr:"Ça faisait des mois qu'ils négociaient quand tout a capoté.", en:"Llevaban meses negociando cuando todo se vino abajo.", alt:["Llevaban meses de negociación cuando todo se vino abajo."], cat:"Passé", point:"llevar + durée + gérondif", note:"« llevar + temps + gérondif » remplace « ça faisait… que ». Et « venirse abajo » = s'effondrer, capoter.", level:"C1" },
  { fr:"Il a fallu trois réunions pour qu'ils se mettent d'accord.", en:"Hicieron falta tres reuniones para que se pusieran de acuerdo.", alt:["Hicieron falta tres reuniones para que llegaran a un acuerdo."], cat:"Passé", point:"hacer falta + para que + subj.", note:"« hacer falta » s'accorde avec ce qui manque : hicieron falta tres reuniones. Et « ponerse de acuerdo ».", level:"C1" },
  { fr:"Je n'avais jamais rien vu de pareil jusqu'à ce jour-là.", en:"Nunca había visto nada igual hasta aquel día.", alt:["Jamás había visto nada parecido hasta aquel día."], cat:"Passé", point:"nunca había + participe", note:"« nada igual » / « nada parecido » = rien de tel. Et « aquel » marque la distance dans le temps.", level:"B2" },

  /* --- Ser / Estar --- */
  { fr:"La réunion est dans la salle du fond, à onze heures.", en:"La reunión es en la sala del fondo, a las once.", alt:["La reunión tiene lugar en la sala del fondo, a las once."], cat:"Ser/Estar", point:"ser pour un événement qui a lieu", note:"Piège classique : un événement « es » quelque part, même pour un lieu. « está » servirait pour un objet.", level:"B2" },
  { fr:"Il est très intelligent, mais aujourd'hui il est insupportable.", en:"Es muy inteligente, pero hoy está insoportable.", alt:["Es listísimo, pero hoy está insoportable."], cat:"Ser/Estar", point:"ser (trait) vs estar (état passager)", note:"Le même adjectif change de sens selon l'auxiliaire : « es insoportable » (par nature) ≠ « está insoportable » (aujourd'hui).", level:"B2" },
  { fr:"Les billets sont épuisés depuis ce matin.", en:"Las entradas están agotadas desde esta mañana.", alt:["Las entradas se agotaron esta mañana."], cat:"Ser/Estar", point:"estar + participe (résultat)", note:"« estar agotado » décrit le résultat ; « ser agotado » n'existe pas. Et « la entrada » = le billet de spectacle.", level:"B2" },
  { fr:"Il est de Valence, mais ça fait vingt ans qu'il vit à Bilbao.", en:"Es de Valencia, pero lleva veinte años viviendo en Bilbao.", alt:["Es valenciano, pero lleva veinte años en Bilbao."], cat:"Ser/Estar", point:"ser de (origine) + llevar + gérondif", note:"L'origine est une identité → ser. Et « llevar + durée + gérondif » pour une situation qui dure encore.", level:"B2" },
  { fr:"Tout était prêt, mais personne n'était d'accord.", en:"Todo estaba listo, pero nadie estaba de acuerdo.", alt:["Todo estaba preparado, pero nadie estaba de acuerdo."], cat:"Ser/Estar", point:"estar listo ≠ ser listo", note:"« estar listo » = être prêt · « ser listo » = être malin. Une des erreurs les plus coûteuses à l'oral.", level:"B2" },
  { fr:"Le problème, c'est que le poste est très mal payé.", en:"El problema es que el puesto está muy mal pagado.", alt:["El problema es que el puesto está mal remunerado."], cat:"Ser/Estar", point:"estar pagado (état constaté)", note:"« está mal pagado » décrit la situation du poste. Et « el puesto » = le poste de travail.", level:"B2" },
  { fr:"Elle est malade depuis mardi, mais ce n'est pas grave.", en:"Está enferma desde el martes, pero no es grave.", alt:["Lleva enferma desde el martes, pero no es grave."], cat:"Ser/Estar", point:"estar enfermo + ser grave", note:"L'état de la personne → estar ; la qualification de la maladie → ser. Les deux auxiliaires dans une seule phrase.", level:"B1" },
  { fr:"Ce n'est pas que je sois contre : c'est que je ne suis pas convaincu.", en:"No es que esté en contra: es que no estoy convencido.", alt:["No es que me oponga: es que no estoy convencido."], cat:"Ser/Estar", point:"no es que + subj. / es que + ind.", note:"Structure très parlée : « no es que… » rejette une interprétation (subjonctif), « es que… » donne la vraie raison (indicatif).", level:"C1" },
  { fr:"La porte était ouverte et la maison, vide.", en:"La puerta estaba abierta y la casa, vacía.", alt:["La puerta estaba abierta y la casa, desierta."], cat:"Ser/Estar", point:"estar + participe/adjectif (constat)", note:"Deux constats visuels → estar. La virgule remplace le verbe répété, comme en français.", level:"B1" },
  { fr:"Il est d'une humeur massacrante aujourd'hui.", en:"Hoy está de un humor de perros.", alt:["Hoy está de mal humor."], cat:"Ser/Estar", point:"estar de + humeur", note:"« estar de buen/mal humor », et l'expression imagée « de perros », qui vaut aussi pour le temps : un día de perros.", level:"C1" },

  /* --- Por / Para --- */
  { fr:"Merci d'être venu : ça comptait beaucoup pour moi.", en:"Gracias por venir: significaba mucho para mí.", alt:["Gracias por haber venido: significaba mucho para mí."], cat:"Por/Para", point:"gracias POR + para mí", note:"« gracias por + infinitif ». Et le destinataire du sentiment → para mí.", level:"B1" },
  { fr:"Nous l'avons appris par la presse, pas par l'entreprise.", en:"Nos enteramos por la prensa, no por la empresa.", alt:["Lo supimos por la prensa, no por la empresa."], cat:"Por/Para", point:"por = le canal, le moyen", note:"« enterarse de algo por alguien » = l'apprendre par quelqu'un. Le moyen est toujours « por ».", level:"B2" },
  { fr:"Pour un débutant, il se débrouille remarquablement bien.", en:"Para ser principiante, se defiende muy bien.", alt:["Para ser novato, se maneja muy bien."], cat:"Por/Para", point:"para + comparaison implicite", note:"« para ser… » = pour quelqu'un qui est… Et « defenderse » = se débrouiller, s'en sortir.", level:"C1" },
  { fr:"Ils ont fermé la rue pour travaux pendant trois mois.", en:"Cortaron la calle por obras durante tres meses.", alt:["Cerraron la calle por obras durante tres meses."], cat:"Por/Para", point:"por = cause", note:"« cortar una calle » est le verbe exact pour une rue barrée. Et la cause reste « por ».", level:"B1" },
  { fr:"Le dossier doit être rendu pour vendredi au plus tard.", en:"El expediente hay que entregarlo para el viernes como muy tarde.", alt:["El expediente debe entregarse para el viernes a más tardar."], cat:"Por/Para", point:"para = échéance", note:"« para el viernes » = pour vendredi (date limite). « por el viernes » voudrait dire : vers vendredi.", level:"B2" },
  { fr:"Il a fait tout ça pour rien : le poste était déjà pourvu.", en:"Hizo todo eso para nada: el puesto ya estaba cubierto.", alt:["Hizo todo aquello en balde: el puesto ya estaba cubierto."], cat:"Por/Para", point:"para nada / en balde", note:"« para nada » = pour rien, en vain (et aussi « pas du tout » en réponse). « cubierto » = pourvu, pour un poste.", level:"B2" },
  { fr:"Ils se sont battus pour leurs droits pendant quinze ans.", en:"Lucharon por sus derechos durante quince años.", alt:["Pelearon por sus derechos durante quince años."], cat:"Por/Para", point:"luchar POR (la cause défendue)", note:"On lutte « por » ce qu'on défend, et « contra » ce qu'on combat. Jamais « luchar para » dans ce sens.", level:"B1" },
  { fr:"Je passe te prendre vers huit heures, ça te va ?", en:"Paso a recogerte sobre las ocho, ¿te viene bien?", alt:["Me paso a por ti sobre las ocho, ¿te va bien?"], cat:"Por/Para", point:"ir a por + venir bien", note:"« ir a por alguien » = aller chercher quelqu'un (Espagne). Et « ¿te viene bien? » = ça t'arrange ?", level:"B2" },
  { fr:"On l'a remercié pour son travail et il a été licencié le mois suivant.", en:"Le dieron las gracias por su trabajo y lo despidieron al mes siguiente.", alt:["Le agradecieron el trabajo y lo despidieron al mes siguiente."], cat:"Por/Para", point:"dar las gracias por ≠ agradecer algo", note:"Deux constructions : « dar las gracias POR algo » mais « agradecer ALGO » (sans préposition).", level:"C1" },
  { fr:"Pour moi, ce n'est pas une question d'argent mais de principe.", en:"Para mí no es una cuestión de dinero sino de principios.", alt:["En mi opinión no es cuestión de dinero sino de principios."], cat:"Por/Para", point:"para mí (opinion) + sino", note:"L'opinion s'introduit par « para mí ». Et après une négation, « sino » (et non « pero ») introduit la correction.", level:"B2" },

  /* --- Gustar & pronoms --- */
  { fr:"Ce qui me plaît le plus chez elle, c'est sa façon d'écouter.", en:"Lo que más me gusta de ella es cómo escucha.", alt:["Lo que más me gusta de ella es su manera de escuchar."], cat:"Gustar & pronoms", point:"lo que más me gusta DE alguien", note:"« gustar de alguien » pour un trait : me gusta de ella. Et « lo que » neutre en tête de phrase clivée.", level:"B2" },
  { fr:"Ça ne nous dérange pas d'attendre encore un peu.", en:"No nos importa esperar un poco más.", alt:["No nos molesta esperar un poco más."], cat:"Gustar & pronoms", point:"importar construit comme gustar", note:"« no me importa » = ça ne me dérange pas. Le sujet est l'infinitif, la personne au datif.", level:"B2" },
  { fr:"Il lui manque encore deux matières pour finir.", en:"Le quedan dos asignaturas para terminar.", alt:["Le faltan dos asignaturas para terminar."], cat:"Gustar & pronoms", point:"quedar/faltar + datif", note:"« le quedan dos » : le sujet est « dos asignaturas », donc verbe au pluriel. La personne reste au datif.", level:"B2" },
  { fr:"J'ai oublié ton livre à la maison, désolé.", en:"Se me ha olvidado tu libro en casa, lo siento.", alt:["Me he dejado tu libro en casa, lo siento."], cat:"Gustar & pronoms", point:"se me olvidó (l'oubli involontaire)", note:"L'espagnol décharge la responsabilité : le livre s'est oublié à moi. Et « dejarse algo » = oublier quelque chose quelque part.", level:"C1" },
  { fr:"Le téléphone lui est tombé des mains et l'écran s'est cassé.", en:"Se le cayó el móvil y se rompió la pantalla.", alt:["Se le cayó el teléfono y se le rompió la pantalla."], cat:"Gustar & pronoms", point:"se + datif d'involontarité", note:"« se me cayó », « se nos rompió », « se te perdió » : l'accident sans coupable, structure très fréquente.", level:"C1" },
  { fr:"Je le lui ai dit hier, mais il ne m'a pas écouté.", en:"Se lo dije ayer, pero no me hizo caso.", alt:["Se lo comenté ayer, pero no me hizo caso."], cat:"Gustar & pronoms", point:"le + lo → se lo", note:"Deux pronoms de 3e personne : « le lo » devient « se lo ». Et « hacer caso a alguien » = écouter, tenir compte.", level:"B2" },
  { fr:"Donne-les-moi, je m'en occupe.", en:"Dámelos, ya me encargo yo.", alt:["Pásamelos, ya me ocupo yo."], cat:"Gustar & pronoms", point:"enclise + accent écrit", note:"Les pronoms se collent à l'impératif et l'accent devient obligatoire : dámelos. Et « encargarse DE » = s'occuper de.", level:"B2" },
  { fr:"Ça me fait de la peine qu'ils partent si vite.", en:"Me da pena que se vayan tan pronto.", alt:["Me apena que se marchen tan pronto."], cat:"Gustar & pronoms", point:"dar pena + que + subj.", note:"Famille entière : me da pena, me da rabia, me da igual, me da miedo — toujours suivie du subjonctif.", level:"B2" },
  { fr:"À moi, ça m'est complètement égal.", en:"A mí me da exactamente igual.", alt:["A mí me da lo mismo."], cat:"Gustar & pronoms", point:"a mí redondant (emphase)", note:"Le « a mí » n'est pas une faute : il insiste. L'espagnol double couramment le pronom pour marquer le contraste.", level:"B1" },
  { fr:"Il ne reste que dix minutes et il nous manque trois signatures.", en:"Solo quedan diez minutos y nos faltan tres firmas.", alt:["Quedan diez minutos nada más y nos faltan tres firmas."], cat:"Gustar & pronoms", point:"quedar (impersonnel) vs faltar (datif)", note:"« quedan diez minutos » sans datif ; « nos faltan tres firmas » avec. Les deux verbes accordent avec leur sujet.", level:"B2" },

  /* --- Hypothèse C1 --- */
  { fr:"Si j'avais su, je ne serais jamais venu.", en:"Si lo hubiera sabido, no habría venido nunca.", alt:["De haberlo sabido, no habría venido nunca."], cat:"Hypothèse C1", point:"si + pluscuamperfecto subj. → condicional compuesto", note:"Irréel du passé. La variante « de + infinitif composé » est très élégante : de haberlo sabido.", level:"C1" },
  { fr:"Si tu étais à ma place, tu ferais exactement pareil.", en:"Si estuvieras en mi lugar, harías exactamente lo mismo.", alt:["Si te vieras en mi situación, harías lo mismo."], cat:"Hypothèse C1", point:"si + imparfait subj. → conditionnel", note:"Irréel du présent. ⚠️ Jamais de conditionnel après « si » en espagnol : « si tendría » est une faute lourde.", level:"B2" },
  { fr:"Si tu n'avais pas insisté, nous n'aurions pas le contrat aujourd'hui.", en:"Si no hubieras insistido, hoy no tendríamos el contrato.", alt:["De no haber insistido, hoy no tendríamos el contrato."], cat:"Hypothèse C1", point:"condition passée, conséquence présente", note:"Hypothèse mixte : subjonctif plus-que-parfait + conditionnel simple. Très fréquente et souvent ratée.", level:"C1" },
  { fr:"Au cas où il appellerait, dis-lui que je suis en réunion.", en:"Por si llama, dile que estoy reunido.", alt:["En caso de que llame, dile que estoy reunido."], cat:"Hypothèse C1", point:"por si + indicatif / en caso de que + subj.", note:"« por si » se construit avec l'indicatif ; « en caso de que » avec le subjonctif. Deux outils, deux modes.", level:"C1" },
  { fr:"Même s'il me le demandait à genoux, je refuserais.", en:"Aunque me lo pidiera de rodillas, me negaría.", alt:["Aun cuando me lo pidiera de rodillas, me negaría."], cat:"Hypothèse C1", point:"aunque + subj. imparfait (hypothèse)", note:"« aunque » + subjonctif imparfait pose une hypothèse peu probable ; + indicatif, il admettrait un fait réel.", level:"C1" },
  { fr:"À moins qu'ils ne changent d'avis, le projet est mort.", en:"A menos que cambien de idea, el proyecto está muerto.", alt:["Salvo que cambien de idea, el proyecto está muerto."], cat:"Hypothèse C1", point:"a menos que / salvo que + subj.", note:"Ces conjonctions imposent toujours le subjonctif. Et « cambiar de idea », avec « de », sans article.", level:"C1" },
  { fr:"Si seulement j'avais écouté mon père à l'époque.", en:"Ojalá hubiera escuchado a mi padre entonces.", alt:["Ojalá le hubiera hecho caso a mi padre entonces."], cat:"Hypothèse C1", point:"ojalá + pluscuamperfecto subj.", note:"« ojalá » + subjonctif plus-que-parfait = le regret sur le passé. Avec le présent du subjonctif, ce serait un souhait.", level:"C1" },
  { fr:"Si tu m'avais prévenu, je t'aurais attendu.", en:"Si me hubieras avisado, te habría esperado.", alt:["Si me llegas a avisar, te espero."], cat:"Hypothèse C1", point:"variante familière : llegar a + inf.", note:"La variante orale « si me llegas a avisar, te espero » est extrêmement courante en Espagne et vaut un irréel du passé.", level:"C1" },
  { fr:"Sans ton aide, je n'y serais jamais arrivé.", en:"Sin tu ayuda, no lo habría conseguido nunca.", alt:["De no ser por ti, no lo habría conseguido nunca."], cat:"Hypothèse C1", point:"sin + nom = condition implicite", note:"« de no ser por » = sans, n'eût été. Et « conseguirlo » = y arriver, y parvenir.", level:"C1" },
  { fr:"Comme si ça ne suffisait pas, il s'est mis à pleuvoir.", en:"Como si fuera poco, se puso a llover.", alt:["Por si fuera poco, se puso a llover."], cat:"Hypothèse C1", point:"como si / por si + subj. imparfait", note:"« como si » exige toujours le subjonctif imparfait ou plus-que-parfait, jamais le présent.", level:"C1" },

  /* --- Impératif --- */
  { fr:"Ne me le dis pas maintenant, j'ai besoin de me concentrer.", en:"No me lo digas ahora, necesito concentrarme.", alt:["No me lo cuentes ahora, necesito concentrarme."], cat:"Impératif", point:"impératif négatif = subjonctif + pronoms devant", note:"À la forme négative, les pronoms passent DEVANT et le verbe prend le subjonctif : no me lo digas.", level:"B1" },
  { fr:"Asseyez-vous et attendez qu'on vous appelle.", en:"Siéntense y esperen a que los llamen.", alt:["Siéntese y espere a que lo llamen."], cat:"Impératif", point:"impératif de vouvoiement + esperar A que", note:"Le vouvoiement emprunte le subjonctif : siéntense, esperen. Et « esperar a que » + subjonctif.", level:"B2" },
  { fr:"Fais-moi confiance et ne t'inquiète pas pour ça.", en:"Fíate de mí y no te preocupes por eso.", alt:["Confía en mí y no te preocupes por eso."], cat:"Impératif", point:"fiarse DE / confiar EN", note:"Deux verbes proches, deux prépositions différentes. Et l'accent écrit sur fíate (hiatus).", level:"B2" },
  { fr:"Dis-le-lui toi-même, moi je ne m'en mêle pas.", en:"Díselo tú mismo, yo no me meto.", alt:["Cuéntaselo tú mismo, yo no me meto."], cat:"Impératif", point:"díselo + meterse", note:"« se lo » collé à l'impératif donne « díselo », avec accent. Et « no me meto » = je ne m'en mêle pas.", level:"B2" },
  { fr:"Allons-y, sinon nous allons rater le train.", en:"Vámonos, que si no perdemos el tren.", alt:["Vámonos ya, que vamos a perder el tren."], cat:"Impératif", point:"vámonos (chute du -s)", note:"« vamos + nos » donne « vámonos » : le -s du verbe tombe. Et « perder el tren », jamais « fallar ».", level:"B2" },
  { fr:"Ne vous en faites pas, on s'occupe de tout.", en:"No se preocupen, nosotros nos encargamos de todo.", alt:["No se preocupe, nosotros nos encargamos de todo."], cat:"Impératif", point:"vouvoiement pluriel + encargarse de", note:"« no se preocupen » (ustedes). Et le pronom sujet « nosotros » insiste sur le contraste.", level:"B1" },
  { fr:"Prends ton temps, mais rends-le-moi avant lundi.", en:"Tómate tu tiempo, pero devuélvemelo antes del lunes.", alt:["Tómate el tiempo que necesites, pero devuélvemelo antes del lunes."], cat:"Impératif", point:"trois syllabes de pronoms : devuélvemelo", note:"Ordre fixe des enclitiques : verbe + datif + accusatif. L'accent reste sur la syllabe d'origine.", level:"C1" },
  { fr:"Que personne ne sorte avant la fin de l'épreuve.", en:"Que no salga nadie antes de que termine la prueba.", alt:["Que nadie salga hasta que termine la prueba."], cat:"Impératif", point:"que + subj. (ordre à la 3e personne)", note:"Un ordre à la troisième personne passe par « que + subjonctif ». Et « antes de que » + subjonctif, toujours.", level:"C1" },

  /* --- Verbos & régime --- */
  { fr:"Il a fini par accepter ce qu'il refusait depuis des mois.", en:"Acabó aceptando lo que llevaba meses rechazando.", alt:["Terminó aceptando lo que llevaba meses rechazando."], cat:"Verbos & régime", point:"acabar + gérondif (finir par)", note:"« acabar/terminar + gérondif » = finir par. ⚠️ « acabar de + infinitif » veut dire venir de : deux structures opposées.", level:"C1" },
  { fr:"Il est devenu insupportable depuis sa promotion.", en:"Se ha vuelto insoportable desde que lo ascendieron.", alt:["Se ha puesto insoportable desde que lo ascendieron."], cat:"Verbos & régime", point:"volverse (changement durable de caractère)", note:"« volverse » = devenir, durablement · « ponerse » = devenir, momentanément · « hacerse » = devenir par effort.", level:"C1" },
  { fr:"Elle est devenue médecin à trente-cinq ans.", en:"Se hizo médica a los treinta y cinco años.", alt:["Llegó a ser médica a los treinta y cinco años."], cat:"Verbos & régime", point:"hacerse (changement voulu)", note:"Un métier ou une conviction → « hacerse ». Et « llegar a ser » insiste sur l'aboutissement d'un parcours.", level:"B2" },
  { fr:"Je me suis rendu compte de l'erreur en relisant le contrat.", en:"Me di cuenta del error al releer el contrato.", alt:["Caí en la cuenta del error al releer el contrato."], cat:"Verbos & régime", point:"darse cuenta DE + al + infinitif", note:"« darse cuenta de algo ». Et « al + infinitif » = en faisant quelque chose, au moment où.", level:"B2" },
  { fr:"Il tient de son père pour le caractère.", en:"Ha salido a su padre en el carácter.", alt:["Se parece a su padre en el carácter."], cat:"Verbos & régime", point:"salir A alguien = tenir de", note:"« salir a alguien » = tenir de quelqu'un (physiquement ou de caractère). Et « parecerse A alguien ».", level:"C1" },
  { fr:"Nous comptons sur toi pour la présentation de jeudi.", en:"Contamos contigo para la presentación del jueves.", alt:["Confiamos en ti para la presentación del jueves."], cat:"Verbos & régime", point:"contar CON + conmigo/contigo", note:"« contar con alguien » = compter sur. Les formes soudées conmigo, contigo, consigo sont obligatoires.", level:"B1" },
  { fr:"Il a renoncé au poste pour s'occuper de ses parents.", en:"Renunció al puesto para cuidar de sus padres.", alt:["Rechazó el puesto para cuidar a sus padres."], cat:"Verbos & régime", point:"renunciar A ≠ rechazar", note:"« renunciar a algo » (y renoncer) ≠ « rechazar algo » (le refuser). Et « cuidar a / cuidar de » sont tous deux corrects.", level:"B2" },
  { fr:"Il s'obstine à nier l'évidence.", en:"Se empeña en negar lo evidente.", alt:["Se obstina en negar lo evidente."], cat:"Verbos & régime", point:"empeñarse EN + lo + adjectif", note:"« empeñarse en » = s'obstiner à. Et « lo evidente » = l'évidence, le neutre qui substantive l'adjectif.", level:"C1" },
  { fr:"Elle s'est mise à pleurer sans qu'on comprenne pourquoi.", en:"Se echó a llorar sin que nadie entendiera por qué.", alt:["Se puso a llorar sin que nadie entendiera por qué."], cat:"Verbos & régime", point:"echarse a + inf. (déclenchement brusque)", note:"« echarse a llorar / a reír / a correr » : le début soudain. Et « sin que » exige toujours le subjonctif.", level:"C1" },
  { fr:"Ils ont dû renoncer au voyage faute de temps.", en:"Tuvieron que renunciar al viaje por falta de tiempo.", alt:["Se vieron obligados a renunciar al viaje por falta de tiempo."], cat:"Verbos & régime", point:"verse obligado a (contrainte subie)", note:"« verse obligado a » = se voir contraint de, plus élégant que « tener que » dans un texte écrit.", level:"C1" },

  /* --- Futur / Conditionnel --- */
  { fr:"D'ici à la fin de l'année, ils auront fermé la moitié des agences.", en:"De aquí a final de año habrán cerrado la mitad de las sucursales.", alt:["Para final de año habrán cerrado la mitad de las oficinas."], cat:"Futur/Conditionnel", point:"futur antérieur + de aquí a", note:"Action achevée dans l'avenir → « habrán cerrado ». Et « para + date » marque aussi l'échéance.", level:"C1" },
  { fr:"Je t'avais dit que ça finirait mal.", en:"Ya te dije que acabaría mal.", alt:["Te lo advertí: acabaría mal."], cat:"Futur/Conditionnel", point:"futur dans le passé → conditionnel", note:"Le futur vu depuis le passé devient conditionnel : « acabaría ». Et « ya » marque le reproche.", level:"B2" },
  { fr:"On aurait dit qu'il savait déjà tout.", en:"Parecía que ya lo sabía todo.", alt:["Diríase que ya lo sabía todo."], cat:"Futur/Conditionnel", point:"on aurait dit = parecía que", note:"L'espagnol n'emploie pas le conditionnel ici : « parecía que ». La forme « diríase » est littéraire.", level:"C1" },
  { fr:"Est-ce que tu pourrais me rendre un service ?", en:"¿Podrías hacerme un favor?", alt:["¿Te importaría hacerme un favor?"], cat:"Futur/Conditionnel", point:"conditionnel de politesse", note:"« hacer un favor », jamais « dar ». Et « ¿te importaría…? » est encore plus poli.", level:"B1" },
  { fr:"Ils auraient déjà dû nous répondre.", en:"Ya tendrían que habernos contestado.", alt:["Ya deberían habernos contestado."], cat:"Futur/Conditionnel", point:"deberían + infinitif composé (reproche)", note:"« deberían haber + participe » = ils auraient dû. Le pronom se colle à l'infinitif : habernos contestado.", level:"C1" },
  { fr:"À ce rythme, nous n'aurons pas fini avant minuit.", en:"A este paso, no habremos terminado antes de medianoche.", alt:["A este ritmo, no habremos acabado antes de medianoche."], cat:"Futur/Conditionnel", point:"a este paso + futur antérieur", note:"« a este paso » = à ce rythme, à ce train-là. Expression figée très fréquente à l'oral.", level:"B2" },
  { fr:"Il ne manquerait plus que ce soit nous qui payions.", en:"Solo faltaría que lo pagáramos nosotros.", alt:["Lo que faltaba: que lo pagáramos nosotros."], cat:"Futur/Conditionnel", point:"solo faltaría que + subj. imparfait", note:"Conditionnel dans la principale → subjonctif imparfait derrière. Expression d'indignation très idiomatique.", level:"C1" },
  { fr:"Nous vous tiendrons informés dès que nous en saurons plus.", en:"Les mantendremos informados en cuanto sepamos algo más.", alt:["Les iremos informando en cuanto sepamos algo más."], cat:"Futur/Conditionnel", point:"futur + en cuanto + subj.", note:"Deux temps différents de part et d'autre : futur dans la principale, subjonctif présent dans la temporelle.", level:"B2" },

  /* --- Nuances C2 --- */
  { fr:"Loin de calmer le débat, sa sortie l'a envenimé.", en:"Lejos de calmar el debate, sus palabras lo enconaron.", alt:["Lejos de apaciguar el debate, sus palabras lo agravaron."], cat:"Nuances C2", point:"lejos de + infinitif", note:"« lejos de + inf. » = loin de. Et « enconar » = envenimer (un conflit, une plaie).", level:"C1" },
  { fr:"Il ne s'agit pas tant d'argent que de confiance.", en:"No se trata tanto de dinero como de confianza.", alt:["No es tanto una cuestión de dinero como de confianza."], cat:"Nuances C2", point:"no tanto… como…", note:"« tratarse de » est impersonnel : jamais de sujet. On ne dit pas « el problema se trata de ».", level:"C1" },
  { fr:"Tout indique que la décision était prise d'avance.", en:"Todo apunta a que la decisión estaba tomada de antemano.", alt:["Todo indica que la decisión ya estaba tomada."], cat:"Nuances C2", point:"todo apunta a que + ind.", note:"« de antemano » = d'avance, au préalable. Et « la decisión estaba tomada » : estar + participe pour le résultat.", level:"C1" },
  { fr:"Au fur et à mesure que l'enquête avance, le dossier s'épaissit.", en:"A medida que avanza la investigación, el caso se complica.", alt:["Conforme avanza la investigación, el caso se complica."], cat:"Nuances C2", point:"a medida que / conforme", note:"Simultanéité progressive. Noter l'inversion sujet-verbe après la conjonction : « a medida que avanza la investigación ».", level:"C1" },
  { fr:"C'est précisément ce qu'il fallait éviter.", en:"Es justo lo que había que evitar.", alt:["Es precisamente lo que había que evitar."], cat:"Nuances C2", point:"lo que había que + infinitif", note:"« había que » = il fallait (impersonnel). Avec « tenía que », on désignerait quelqu'un en particulier.", level:"C1" },
  { fr:"Non seulement il a démissionné, mais il a tout emporté avec lui.", en:"No solo dimitió, sino que se lo llevó todo consigo.", alt:["No solo dimitió, sino que además se lo llevó todo."], cat:"Nuances C2", point:"no solo… sino que…", note:"Devant un VERBE conjugué, c'est « sino que » (et non « sino » seul). Et « consigo » = avec lui.", level:"C1" },
  { fr:"Il a beau insister, personne ne le croit.", en:"Por mucho que insista, nadie le cree.", alt:["Por más que insista, nadie le cree."], cat:"Nuances C2", point:"por mucho que + subj.", note:"« por mucho que », « por más que », « por muy + adjectif + que » : la concession intensive, toujours au subjonctif.", level:"C1" },
  { fr:"Ce n'est qu'en partant qu'il a compris ce qu'il perdait.", en:"Solo al marcharse entendió lo que estaba perdiendo.", alt:["No fue hasta que se marchó cuando entendió lo que perdía."], cat:"Nuances C2", point:"solo al + infinitif", note:"« al marcharse » = en partant, au moment de partir. L'infinitif espagnol remplace souvent une subordonnée française.", level:"C1" },
  { fr:"Quant à savoir qui décidera, personne n'ose le dire.", en:"En cuanto a quién decidirá, nadie se atreve a decirlo.", alt:["Respecto a quién decidirá, nadie se atreve a decirlo."], cat:"Nuances C2", point:"en cuanto a + interrogative indirecte", note:"« quién » garde son accent dans l'interrogative indirecte. Et « atreverse A + infinitif ».", level:"C1" },
  { fr:"Si tant est qu'on puisse encore parler d'un accord.", en:"Si es que todavía se puede hablar de un acuerdo.", alt:["Suponiendo que todavía quepa hablar de un acuerdo."], cat:"Nuances C2", point:"si es que / caber + infinitif", note:"« caber hablar de » = il y a lieu de parler de, registre très soutenu. « si es que » est la version courante.", level:"C1" },

  /* --- Expressions --- */
  { fr:"Ça n'a rien à voir avec ce dont nous avions parlé.", en:"No tiene nada que ver con lo que habíamos hablado.", alt:["No guarda relación con lo que habíamos hablado."], cat:"Expressions", point:"no tener nada que ver con", note:"Et « lo que » neutre reprend un contenu entier. On dit « hablar de algo », d'où « lo que habíamos hablado ».", level:"B1" },
  { fr:"Il s'en est fallu de peu qu'on rate l'avion.", en:"Por poco perdemos el avión.", alt:["Casi perdemos el avión."], cat:"Expressions", point:"por poco + PRÉSENT", note:"Curiosité espagnole : « por poco » se construit au présent même pour un fait passé. « Por poco me caigo » = j'ai failli tomber.", level:"C1" },
  { fr:"Ça fait des années qu'on nous promet la même chose.", en:"Llevan años prometiéndonos lo mismo.", alt:["Hace años que nos prometen lo mismo."], cat:"Expressions", point:"llevar + durée + gérondif", note:"Deux tournures équivalentes : « llevan años prometiendo » et « hace años que prometen ». La première est plus idiomatique.", level:"B2" },
  { fr:"Autant te le dire tout de suite : ce ne sera pas possible.", en:"Más vale que te lo diga ya: no va a poder ser.", alt:["Te lo digo desde ya: no va a poder ser."], cat:"Expressions", point:"más vale que + subj. + no poder ser", note:"« no va a poder ser » = ça ne va pas être possible, formule toute faite du refus poli.", level:"C1" },
  { fr:"Il s'est débrouillé tout seul, comme toujours.", en:"Se las arregló él solo, como siempre.", alt:["Se apañó él solo, como siempre."], cat:"Expressions", point:"arreglárselas / apañárselas", note:"Verbes à pronoms figés : « arreglárselas », « apañárselas », « ingeniárselas » = se débrouiller. Le « las » ne renvoie à rien.", level:"C1" },
  { fr:"Ne te fais pas d'illusions : ils ne rappelleront pas.", en:"No te hagas ilusiones: no van a volver a llamar.", alt:["No te ilusiones: no van a volver a llamar."], cat:"Expressions", point:"hacerse ilusiones + volver a + inf.", note:"« volver a + infinitif » = refaire quelque chose. L'espagnol n'a pas de préfixe systématique comme notre « re- ».", level:"B2" },
  { fr:"Il a mis les pieds dans le plat devant tout le monde.", en:"Metió la pata delante de todo el mundo.", alt:["Metió la pata hasta el fondo delante de todos."], cat:"Expressions", point:"meter la pata", note:"Expression centrale du registre familier : faire une gaffe. Et « meterse en un lío » = se fourrer dans un pétrin.", level:"B2" },
  { fr:"Ça ne vaut pas la peine d'insister davantage.", en:"No merece la pena insistir más.", alt:["No vale la pena seguir insistiendo."], cat:"Expressions", point:"merecer / valer la pena", note:"Les deux formes coexistent ; « merecer la pena » est plus fréquente en Espagne. Suivies de l'infinitif.", level:"B1" },
  { fr:"À vrai dire, je n'y avais jamais vraiment réfléchi.", en:"La verdad es que nunca me lo había planteado en serio.", alt:["A decir verdad, nunca me lo había planteado en serio."], cat:"Expressions", point:"plantearse algo", note:"« plantearse algo » = se poser la question de, envisager. Verbe-clé de l'expression d'opinion au C1.", level:"C1" },
  { fr:"Tôt ou tard, quelqu'un finira par poser la question.", en:"Tarde o temprano, alguien acabará preguntándolo.", alt:["Antes o después, alguien acabará haciendo la pregunta."], cat:"Expressions", point:"tarde o temprano + acabar + gérondif", note:"« tarde o temprano » (dans cet ordre, jamais l'inverse). Et « hacer una pregunta », jamais « preguntar una pregunta ».", level:"B2" }

]);
